//! Value-for-value parity for the EKF VIO prediction step.
//!
//! The fixture is generated by `scripts/capture_vio_fixture.py`, which drives
//! the reference with per-frame-unique feature ids so nothing ever matches and
//! the update step cannot fire. It asserts that itself before recording, so a
//! fixture that accidentally exercised the update would fail to generate rather
//! than quietly become a different test.
//!
//! The update step is not compared here at all. Two of its behaviours are ones
//! P4.4 requires changing rather than reproducing -- see
//! `docs/migration/VIO_CONTRACT.md` -- and a parity fixture covering them would
//! bless a scalar update that manufactures a measurement from the feature
//! count.

use argusnet_localization::vio::{ImuMeasurement, VioNoise, VioPredictor};
use serde::Deserialize;

#[derive(Deserialize)]
struct Fixture {
    gravity_world: [String; 3],
    cases: Vec<Case>,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    initial_position: [String; 3],
    steps: Vec<Step>,
}

#[derive(Deserialize)]
struct Step {
    timestamp_s: String,
    imu_fed: Vec<Imu>,
    expected: Expected,
}

#[derive(Deserialize)]
struct Imu {
    timestamp_s: String,
    angular_velocity: [String; 3],
    linear_acceleration: [String; 3],
}

#[derive(Deserialize)]
struct Expected {
    state: Vec<String>,
    covariance: Vec<String>,
    position: [String; 3],
    velocity: [String; 3],
    covariance_pos_trace: String,
}

/// Floats cross as strings; `str::parse` is exact where `serde_json`'s parser
/// is off by an ULP. In a filter integrating over many steps an ULP at the
/// input is not an ULP at the output.
fn f(text: &str) -> f64 {
    text.parse().expect("fixture float")
}

fn triple(values: &[String; 3]) -> [f64; 3] {
    [f(&values[0]), f(&values[1]), f(&values[2])]
}

fn load() -> Fixture {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/fixtures/vio_prediction.json"
    );
    let text = std::fs::read_to_string(path).expect("fixture readable");
    serde_json::from_str(&text).expect("fixture parses")
}

/// Relative tolerance. The reference propagates covariance as
/// `F @ P @ F.T + Q`, and numpy's matmul may sum a row in a different order
/// from nalgebra's, so exact equality is not available on the covariance the
/// way it was for the closed-form sensor model. 1e-12 relative is roughly four
/// orders of magnitude above the observed disagreement and far below anything
/// a wrong term produces.
const RELATIVE_TOLERANCE: f64 = 1e-12;

fn assert_close(actual: f64, expected: f64, what: &str) {
    let scale = expected.abs().max(actual.abs()).max(1.0);
    let error = (actual - expected).abs() / scale;
    assert!(
        error <= RELATIVE_TOLERANCE,
        "{what}: {actual} vs expected {expected} (relative {error:e})"
    );
}

#[test]
fn the_prediction_step_matches_python_frame_by_frame() {
    let fixture = load();
    for case in &fixture.cases {
        let mut predictor = VioPredictor::new(VioNoise::default());
        predictor.initialize(triple(&case.initial_position), 0.0);

        for (index, step) in case.steps.iter().enumerate() {
            let measurements: Vec<ImuMeasurement> = step
                .imu_fed
                .iter()
                .map(|m| ImuMeasurement {
                    timestamp_s: f(&m.timestamp_s),
                    angular_velocity: triple(&m.angular_velocity),
                    linear_acceleration: triple(&m.linear_acceleration),
                })
                .collect();
            assert!(
                predictor.predict_to(&measurements, f(&step.timestamp_s)),
                "{}: step {index} should have advanced",
                case.name
            );

            for (component, expected) in step.expected.state.iter().enumerate() {
                assert_close(
                    predictor.state()[component],
                    f(expected),
                    &format!("{} step {index} state[{component}]", case.name),
                );
            }
            // Full matrix, row-major. Comparing only the diagonal missed a
            // flipped sign in the gyro-bias Jacobian entirely.
            assert_eq!(
                step.expected.covariance.len(),
                225,
                "covariance must be 15x15"
            );
            for (flat, expected) in step.expected.covariance.iter().enumerate() {
                let (row, col) = (flat / 15, flat % 15);
                assert_close(
                    predictor.covariance()[(row, col)],
                    f(expected),
                    &format!("{} step {index} P[{row},{col}]", case.name),
                );
            }
            for (axis, (actual, expected)) in predictor
                .position()
                .iter()
                .zip(&step.expected.position)
                .enumerate()
            {
                assert_close(
                    *actual,
                    f(expected),
                    &format!("{} step {index} position[{axis}]", case.name),
                );
            }
            for (axis, (actual, expected)) in predictor
                .velocity()
                .iter()
                .zip(&step.expected.velocity)
                .enumerate()
            {
                assert_close(
                    *actual,
                    f(expected),
                    &format!("{} step {index} velocity[{axis}]", case.name),
                );
            }
            assert_close(
                predictor.position_covariance_trace(),
                f(&step.expected.covariance_pos_trace),
                &format!("{} step {index} covariance_pos_trace", case.name),
            );
        }
    }
}

/// The fixture's gravity must be the one the port compiled in. A mismatch
/// would otherwise show up as a slow positional drift that looks like a
/// tolerance problem.
#[test]
fn gravity_agrees_with_the_reference() {
    let fixture = load();
    let expected = triple(&fixture.gravity_world);
    assert_eq!(expected, argusnet_localization::vio::GRAVITY_WORLD);
}

/// Prediction with no measurement must make the filter LESS certain, in every
/// case without exception. This is the property P4.4 protects when it says "no
/// manufactured confidence on a failed estimator": propagating forward adds
/// process noise and nothing subtracts it.
#[test]
fn predicting_without_measurements_always_grows_the_position_covariance() {
    let fixture = load();
    for case in &fixture.cases {
        let first = f(&case.steps[0].expected.covariance_pos_trace);
        let last = f(&case.steps[case.steps.len() - 1]
            .expected
            .covariance_pos_trace);
        assert!(
            last > first,
            "{}: position covariance must grow while only predicting, got {first} then {last}",
            case.name
        );
    }
}

/// Which fixture cases move the state, and which deliberately do not.
///
/// An earlier version of this test asserted that EVERY case moves the state,
/// and `no_imu_constant_velocity` failed it. That was correct of the fixture
/// and wrong of the test: with no IMU the velocity stays zero, so
/// `position += velocity * dt` moves nothing. The case is still worth keeping
/// -- it is the only one exercising the constant-velocity branch in isolation
/// -- but it cannot, on its own, distinguish that branch from doing nothing.
/// `the_constant_velocity_step_actually_uses_the_velocity` below is what pins
/// it, and `imu_gap` reaches the branch with a velocity worth integrating.
#[test]
fn the_moving_fixture_cases_actually_move() {
    let fixture = load();
    for case in &fixture.cases {
        let first = &case.steps[0].expected;
        let last = &case.steps[case.steps.len() - 1].expected;
        let moved = (0..15).any(|i| f(&first.state[i]) != f(&last.state[i]));
        match case.name.as_str() {
            // Zero velocity and zero IMU: nothing to integrate.
            "no_imu_constant_velocity" => assert!(
                !moved,
                "no_imu_constant_velocity is expected NOT to move; if it now \
                 does, the fixture changed and this test's premise with it"
            ),
            // Specific force exactly cancels gravity, so world acceleration is
            // zero and the platform is genuinely still.
            "stationary_gravity_cancelled" => assert!(
                !moved,
                "stationary_gravity_cancelled is expected NOT to move"
            ),
            _ => assert!(moved, "{}: state never changed across the case", case.name),
        }
    }
}

/// The constant-velocity fallback must integrate the velocity it holds, not
/// merely advance the clock. Deleting that line passes every fixture case,
/// because the only case reaching the branch alone has zero velocity.
#[test]
fn the_constant_velocity_step_actually_uses_the_velocity() {
    use argusnet_localization::vio::VioPredictor;
    let mut predictor = VioPredictor::new(VioNoise::default());
    predictor.initialize([0.0, 0.0, 100.0], 0.0);

    // Build velocity with one IMU interval: 2 m/s^2 forward for 0.5 s.
    let accelerating = ImuMeasurement {
        timestamp_s: 0.5,
        angular_velocity: [0.0; 3],
        linear_acceleration: [2.0, 0.0, 9.806_65],
    };
    assert!(predictor.predict_to(&[accelerating], 0.5));
    let velocity = predictor.velocity();
    assert!(
        velocity[0] > 0.9,
        "setup should have produced ~1 m/s of x velocity, got {}",
        velocity[0]
    );

    // Now a frame with NO measurement: the fallback must carry the position
    // forward by velocity * dt.
    let before = predictor.position();
    assert!(predictor.predict_to(&[], 1.5));
    let after = predictor.position();
    let expected = before[0] + velocity[0] * 1.0;
    assert!(
        (after[0] - expected).abs() < 1e-12,
        "constant-velocity step moved x to {} , expected {expected}",
        after[0]
    );
}
